'use strict';
// ---------- global search: chapters and sections, glossary terms, fighters and moves ----------
// Runs entirely in the browser. The text index is built from the page itself the first time the
// search opens; move names come from data/moves-index.js (generated by build.py, loaded on demand).
var search = { ov: null, input: null, out: null, index: null, moves: null, last: null, sel: -1, limit: {} };
var SEARCH_GROUPS = ['fighter', 'matchup', 'section', 'term', 'move'];
var SEARCH_PAGE = 8;

function searchPairs(sec, selector) {   // elements of both languages, paired by position
  var en = sec.querySelectorAll(':scope > .l-en ' + selector), pt = sec.querySelectorAll(':scope > .l-pt ' + selector);
  var out = [];
  for (var i = 0; i < Math.max(en.length, pt.length); i++) out.push({ en: en[i] || pt[i], pt: en.length === pt.length ? pt[i] : (pt[i] || en[i]), paired: en.length === pt.length });
  return out;
}
function searchTextAfter(h, next) {
  var r = document.createRange();
  r.setStartAfter(h);
  if (next) r.setEndBefore(next); else r.setEndAfter(h.closest('.l-en, .l-pt').lastChild);
  var frag = r.cloneContents();   // leave out interactive parts and counters added by the scripts
  frag.querySelectorAll('.widget, .widget-slot, .checklist-bar, .quiz, script, style').forEach(function (x) { x.remove(); });
  return frag.textContent.replace(/\s+/g, ' ').trim();
}
function searchHeadingText(h) {
  var c = h.cloneNode(true);
  c.querySelectorAll('.sf6-tag').forEach(function (x) { x.replaceWith(' ' + x.textContent); });
  return c.textContent.replace(/\s+/g, ' ').trim();
}
function buildSearchIndex() {
  var idx = [];
  document.querySelectorAll('#content > section').forEach(function (sec) {
    var chap = sec.id;
    idx.push({ type: 'section', chap: chap, top: true, title: { en: tx('en', 'chapter.' + chap), pt: tx('pt', 'chapter.' + chap) }, text: { en: '', pt: '' } });
    if (chap === 'glossary') {
      searchPairs(sec, 'dt').forEach(function (p) {
        var e = { type: 'term', chap: chap, el: p, title: {}, text: {} };
        ['en', 'pt'].forEach(function (l) { var dd = p[l].nextElementSibling; e.title[l] = p[l].textContent.replace(/:\s*$/, '').trim(); e.text[l] = dd ? dd.textContent.replace(/\s+/g, ' ').trim() : ''; });
        idx.push(e);
      });
      return;
    }
    var heads = { en: [], pt: [] };
    ['en', 'pt'].forEach(function (l) {
      sec.querySelectorAll(':scope > .l-' + l + ' h3, :scope > .l-' + l + ' h4').forEach(function (h) { if (!h.closest('.widget, .toc')) heads[l].push(h); });
    });
    var paired = heads.en.length === heads.pt.length;
    ['en', 'pt'].forEach(function (l) {
      if (paired && l === 'pt') return;
      heads[l].forEach(function (h, i) {
        var e = { type: 'section', chap: chap, el: { en: h, pt: paired ? heads.pt[i] : h }, title: {}, text: {} };
        (paired ? ['en', 'pt'] : [l]).forEach(function (x) {
          var hh = heads[x][i];
          e.title[x] = searchHeadingText(hh);
          e.text[x] = searchTextAfter(hh, heads[x][i + 1]);
        });
        if (!paired) { var o = l === 'en' ? 'pt' : 'en'; e.title[o] = e.title[l]; e.text[o] = ''; e.only = l; }
        idx.push(e);
      });
    });
  });
  rosterList().forEach(function (c) {
    idx.push({ type: 'fighter', slug: c.slug, title: { en: c.name, pt: c.name }, text: { en: tx('en', 'arch.' + c.archetype), pt: tx('pt', 'arch.' + c.archetype) } });
  });
  idx.forEach(function (e) {
    e.nt = norm(e.title.en + ' ' + e.title.pt);
    e.nx = { en: norm(e.text.en), pt: norm(e.text.pt) };
  });
  return idx;
}
function addMovesToIndex(moves) {
  Object.keys(moves).forEach(function (slug) {
    var name = ROSTER[slug] ? ROSTER[slug].name : slug;
    moves[slug].forEach(function (m) {
      var e = { type: 'move', slug: slug, move: m[0], title: { en: m[0], pt: m[0] }, sub: name + (m[1] ? ' · ' + m[1] : ''), text: { en: '', pt: '' } };
      e.nt = norm(m[0]); e.ni = norm((m[1] || '') + ' ' + (m[2] || '')); e.nx = { en: norm(name) + ' ' + e.ni, pt: '' };
      search.index.push(e);
    });
  });
}
function wordStart(hay, t) {   // position where `t` begins a word in `hay`, or -1
  var from = 0, p;
  while ((p = hay.indexOf(t, from)) > -1) {
    if (p === 0 || !/[a-z0-9]/.test(hay.charAt(p - 1))) return p;
    from = p + 1;
  }
  return -1;
}
function searchQuery(q) {
  var tokens = norm(q).split(/\s+/).filter(Boolean), res = {};
  SEARCH_GROUPS.forEach(function (g) { res[g] = []; });
  if (norm(q).replace(/\s/g, '').length < 2) return res;
  var whole = tokens.join(' '), other = lang === 'en' ? 'pt' : 'en';
  search.index.forEach(function (e, order) {
    var score = 0, where = null;
    var inTitle = 0;
    for (var i = 0; i < tokens.length; i++) {
      var t = tokens[i];
      if (wordStart(e.nt, t) > -1) { score += 14; inTitle++; }
      else if (wordStart(e.nx[lang], t) > -1) { score += 2; where = where || lang; }
      else if (wordStart(e.nx[other], t) > -1) { score += 1; where = where || other; }
      else return;
    }
    if (e.type === 'move' && !inTitle && !tokens.some(function (t) { return wordStart(e.ni, t) > -1; })) return;   // a fighter's name alone doesn't list all of their moves
    score -= Math.min(4, e.nt.length / 40);   // shorter titles first
    if (e.nt === whole) score += 30; else if (e.nt.indexOf(whole) === 0) score += 12; else if (e.nt.indexOf(whole) > -1) score += 6;
    if (e.top) score += 3;
    res[e.type].push({ e: e, score: score, order: order, where: where });
  });
  // two fighters in the query: offer the matchup screen
  var fs = [];
  tokens.forEach(function (t) {
    var hit = rosterList().filter(function (c) { return norm(c.name).split(/[^a-z0-9]+/).indexOf(t) > -1 || norm(c.name) === t || c.slug === t; })[0];
    if (hit && fs.indexOf(hit.slug) === -1) fs.push(hit.slug);
  });
  if (fs.length >= 2) res.matchup.push({ e: { type: 'matchup', me: fs[0], opp: fs[1], title: { en: ROSTER[fs[0]].name + ' vs ' + ROSTER[fs[1]].name, pt: ROSTER[fs[0]].name + ' vs ' + ROSTER[fs[1]].name } }, score: 100, order: 0 });
  SEARCH_GROUPS.forEach(function (g) { res[g].sort(function (a, b) { return b.score - a.score || a.order - b.order; }); });
  return res;
}
function searchSnippet(r, tokens) {
  var e = r.e, l = r.where || lang, text = e.text[l] || e.text[lang] || '';
  if (!text) return '';
  var n = norm(text), pos = -1;
  tokens.forEach(function (t) { var p = wordStart(n, t); if (p > -1 && (pos === -1 || p < pos)) pos = p; });
  if (n.length !== text.length) pos = -1;   // accents changed the length: fall back to the start
  var a = Math.max(0, pos - 50), s = text.slice(a, a + 150);
  return (a > 0 ? '…' : '') + esc(s) + (a + 150 < text.length ? '…' : '');
}
function renderSearch() {
  var q = search.input.value, tokens = norm(q).split(/\s+/).filter(Boolean);
  var res = searchQuery(q), h = '', total = 0;
  search.last = [];
  if (norm(q).replace(/\s/g, '').length < 2) {
    search.out.innerHTML = '<p class="muted small search-hint">' + B('search.hint') + '</p>'; search.sel = -1; return;
  }
  SEARCH_GROUPS.forEach(function (g) {
    var rows = res[g]; if (!rows.length) return;
    total += rows.length;
    var lim = search.limit[g] || SEARCH_PAGE;
    h += '<div class="search-group"><h4>' + B('search.group.' + g) + ' <span class="muted">(' + rows.length + ')</span></h4><ul>';
    rows.slice(0, lim).forEach(function (r) {
      var e = r.e, i = search.last.push(e) - 1, sub = '';
      if (e.type === 'section') sub = e.top ? B('search.chapter') : B('chapter.' + e.chap);
      else if (e.type === 'term') sub = B('chapter.glossary');
      else if (e.type === 'move') sub = esc(e.sub);
      else if (e.type === 'fighter') sub = B('search.fighter-guide') + ' · ' + esc(e.text[lang]);
      else if (e.type === 'matchup') sub = B('chapter.matchup');
      var snip = (e.type === 'section' || e.type === 'term') ? searchSnippet(r, tokens) : '';
      h += '<li><button type="button" class="search-res" data-res="' + i + '"><b>' + esc(e.title[lang]) + '</b><small>' + sub + '</small>' + (snip ? '<span class="search-snip">' + snip + '</span>' : '') + '</button></li>';
    });
    h += '</ul>' + (rows.length > lim ? '<button type="button" class="linkbtn search-more" data-more="' + g + '">' + B('search.more', [rows.length - lim]) + '</button>' : '') + '</div>';
  });
  if (!total) h = '<p class="muted search-hint">' + B('search.none') + '</p>';
  if (!search.moves) h += '<p class="muted small search-hint">' + B(search.movesFailed ? 'search.moves-failed' : 'search.moves-loading') + '</p>';
  search.out.innerHTML = h;
  search.sel = -1;
}
function searchMoveSel(d) {
  var items = search.out.querySelectorAll('.search-res'); if (!items.length) return;
  search.sel = (search.sel + d + items.length) % items.length;
  items.forEach(function (b, i) { b.classList.toggle('sel', i === search.sel); });
  items[search.sel].scrollIntoView({ block: 'nearest' });
}
function flashTarget(el) {
  el.classList.add('search-hit');
  el.scrollIntoView({ behavior: 'instant', block: 'start' });
  setTimeout(function () { el.classList.remove('search-hit'); }, 2600);
}
function goToResult(e) {
  closeSearch();
  if (e.type === 'fighter') { openChar(e.slug); return; }
  if (e.type === 'matchup') { muSet(e.me, e.opp); show('matchup', true); return; }
  if (e.type === 'move') {
    ftState.q = e.move; ftState.cat = 'all'; ftState.unsafe = false;
    openChar(e.slug, false);
    needChar(e.slug).then(function () {
      if (roster.open !== e.slug) return;
      renderRoster();
      var d = rosterApp.querySelector('.ft-details');
      if (d) { d.open = true; flashTarget(d); }
    }, function () {});
    return;
  }
  if (e.top) { show(e.chap, true); return; }
  if (e.type === 'term' && glossaryInput && glossaryInput.value) { glossaryInput.value = ''; }
  show(e.chap, false);
  if (e.type === 'term') runGlossarySearch();
  var el = e.el[lang] || e.el.en;
  if (el.id) { try { history.replaceState(null, '', '#' + el.id); } catch (er) {} }
  flashTarget(el);
}
function openSearch() {
  if (!search.ov) {
    search.ov = el('<div class="search-ov" hidden><div class="search-box" role="dialog" aria-modal="true" data-i18n-aria="search.title" aria-label="Search">' +
      '<div class="search-top"><input type="search" id="site-q" autocomplete="off" spellcheck="false" data-i18n-ph="search.placeholder" data-i18n-aria="search.title" aria-label="Search">' +
      '<button type="button" class="btn ghost" data-search-close>' + B('ui.close') + '</button></div>' +
      '<div class="search-out" aria-live="polite"></div></div></div>');
    document.body.appendChild(search.ov);
    search.input = search.ov.querySelector('#site-q'); search.out = search.ov.querySelector('.search-out');
    search.input.addEventListener('input', function () { search.limit = {}; renderSearch(); });
    search.ov.addEventListener('click', function (e) {
      if (e.target === search.ov || e.target.closest('[data-search-close]')) { closeSearch(); return; }
      var more = e.target.closest('[data-more]');
      if (more) { var g = more.getAttribute('data-more'); search.limit[g] = (search.limit[g] || SEARCH_PAGE) + 20; renderSearch(); return; }
      var r = e.target.closest('[data-res]');
      if (r) goToResult(search.last[+r.getAttribute('data-res')]);
    });
    search.ov.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { e.stopPropagation(); closeSearch(); }
      else if (e.key === 'ArrowDown') { e.preventDefault(); searchMoveSel(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); searchMoveSel(-1); }
      else if (e.key === 'Enter') {
        var items = search.out.querySelectorAll('.search-res');
        var b = items[search.sel < 0 ? 0 : search.sel];
        if (b) { e.preventDefault(); goToResult(search.last[+b.getAttribute('data-res')]); }
      } else if (e.key === 'Tab') {   // keep focus inside the dialog
        var f = search.ov.querySelectorAll('input, button'), first = f[0], lastEl = f[f.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); lastEl.focus(); }
        else if (!e.shiftKey && document.activeElement === lastEl) { e.preventDefault(); first.focus(); }
      }
    });
  }
  if (!search.index) search.index = buildSearchIndex();
  if (!search.moves && !search.movesLoading) {
    search.movesLoading = true; search.movesFailed = false;
    loadScript('data/moves-index.js').then(function () {
      search.moves = window.HUB_DATA.moves || {}; addMovesToIndex(search.moves);
    }, function () { search.movesFailed = true; }).then(function () { search.movesLoading = false; if (!search.ov.hidden) renderSearch(); });
  }
  search.opener = document.activeElement;
  closeMenu();
  search.ov.hidden = false;
  document.documentElement.classList.add('search-open');
  search.input.setAttribute('placeholder', tr('search.placeholder'));
  search.ov.querySelectorAll('[data-i18n-aria]').forEach(function (i) { i.setAttribute('aria-label', tr(i.getAttribute('data-i18n-aria'))); });
  renderSearch();
  search.input.focus(); search.input.select();
}
function closeSearch() {
  if (!search.ov || search.ov.hidden) return;
  search.ov.hidden = true;
  document.documentElement.classList.remove('search-open');
  if (search.opener && search.opener.focus) { try { search.opener.focus({ preventScroll: true }); } catch (e) {} }
}
document.addEventListener('click', function (e) { if (e.target.closest('[data-search-open]')) { e.preventDefault(); openSearch(); } });
document.addEventListener('keydown', function (e) {
  var tag = (e.target.tagName || '').toLowerCase(), typing = tag === 'input' || tag === 'textarea' || tag === 'select' || e.target.isContentEditable;
  if ((e.key === 'k' && (e.ctrlKey || e.metaKey)) || (e.key === '/' && !typing && !e.ctrlKey && !e.metaKey && !e.altKey)) { e.preventDefault(); openSearch(); }
});
